internal TownCouncilState SubmitExpansionLandRequest(ITownWorld world, TownRuntimeState town, TownCouncilState state, string actor, string buildingId)
{
    var building = world.WorldSimulation.Buildings.Single(b => b.InstanceId == buildingId);
    var tiles = ExpansionLandRequestTiles(world, actor, building) ?? throw new InvalidOperationException("The expansion's land need has changed.");
    return SubmitPersonalLandUseRequest(world, town, state, actor, tiles.Select(t => new CognitionLandTile(t.X, t.Y)).ToArray());
}

internal void AcceptTownAdmission(ITownWorld world, string actor, string townId, string proposalId)
{
    var town = towns.Single(item => item.Id == townId);
    if (ApprovedAdmission(world, town, actor) is not { } record || record.ProposalId != proposalId ||
        !MayAcceptAdmission(world, actor, town, record)) return;
    ApplyTownAdmission(world, townId, proposalId, actor, record);
    SettleTownAdmissions(world);
}

internal TownRemedyTerm[] NonLandTerms(ITownWorld world, TownRuntimeState town, string actor, string caseId, CognitionNonLandChoice? payload, string? replacingAgreementId = null)
{
    var references = CaptureNonLandAgreementReferences(world);
    var result = BindNonLandAgreementTerms(caseId, town.NonLandHearings.Sequence, references, payload);
    if (result is not [_, ..])
        throw new InvalidOperationException("A restorative offer needs finite named goods or work.");
    var duration = payload?.CompletionTicks ?? checked(3L * CivicDay(world));
    if (NonLandTermsRefusal(world, town, actor, result, duration, replacingAgreementId) is { } refusal) throw new InvalidOperationException(refusal);
    return result;
}

internal static TownLandRequestedOutcome LandHearingOutcome(ITownWorld world, string kind, CognitionLandHearingChoice? choice)
{
    if (choice?.RequestedOutcome is { } requested && requested != kind)
        throw new InvalidOperationException("The requested outcome contradicts the chosen bounded action.");
    var outcome = new TownLandRequestedOutcome(kind, choice?.HouseholdId, choice?.AgreedEndTick);
    if (!TownLandHearingRules.IsValidOutcome(outcome, world.WorldTick) || outcome.HouseholdId is { } household &&
        !world.Society.Households.Any(item => item.Id == household))
        throw new InvalidOperationException("The land outcome is malformed or names an unknown household.");
    return outcome;
}
